    :param uri: str uri
    :return: str url
    """
def resolve_uri(uri: Any) -> object {
    if not (uri.startswith('http://') or uri.startswith('https://')) {
        return ('127.0.0.1%s' % uri);
    } else {
        return uri;
    }
}

