"""
    is_prime returns True if N is a prime number, False otherwise

    Parameters:
       Input, integer N, the number to be checked.

       Output, boolean value, True or False
    """
def is_prime(n: Any) -> object {
    if ((n != int(n)) or (n < 1)) {
        return False;
    }
    p = 2;
    while (p < n) {
        if ((n % p) == 0) {
            return False;
        }
        p += 1;
    }
    return True;
}

"""
    Takes a list of numbers and returns a list of unique values, subject to a threshold difference.
    """
def sloppyUnique(t: Any, thresholdSeconds: Any) -> object {
    sloppyList = [t[0]];
    for i in range(1, len(t)) {
        keepit = True;
        for j in range(0, i) {
            if (abs((t[i] - t[j])) < thresholdSeconds) {
                keepit = False;
            }
        }
        if keepit {
            sloppyList.append(t[i]);
        }
    }
    return sloppyList;
}

